INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2473150, 340721, 9906, '<td valign="top">You used the camera''s flash on this one.  Makes it look almost artificial.  It also makes it very flat and causes the reflection on her chin.  If you have to use the camera flash, try taping some tissue paper over it to soften it up a touch.<br/>TC</td>', 'You used the camera''s flash on this one.  Makes it look almost artificial.  It also makes it very flat and causes the reflection on her chin.  If you have to use the camera flash, try taping some tissue paper over it to soften it up a touch.TC', '2006-05-31 18:30:16.000000', NULL, 1),
(2473151, 339661, 52675, '<td valign="top">I like this alot.  He definitely looks like a sailor.  I just wish the bottom of the picture wasn''t cropped.</td>', 'I like this alot.  He definitely looks like a sailor.  I just wish the bottom of the picture wasn''t cropped.', '2006-05-31 18:30:17.000000', NULL, 1),
