INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2476666, 339150, 44579, '<td valign="top">I wonder how many DNMC you have recieved...?<br/> <br/>Not from me! 7.</td>', 'I wonder how many DNMC you have recieved...? Not from me! 7.', '2006-06-01 18:11:12.000000', NULL, 1),
(2476670, 340294, 44579, '<td valign="top">Wow! One of the best I''ve seen this challenge. 10.</td>', 'Wow! One of the best I''ve seen this challenge. 10.', '2006-06-01 18:12:45.000000', NULL, 1),
(2476671, 340782, 23430, '<td valign="top">Lovely bright shot. Love your use of lighting to darken the background and bring out the flower. The DOF right through the range of the flower and the contrasty orange colour is great.</td>', 'Lovely bright shot. Love your use of lighting to darken the background and bring out the flower. The DOF right through the range of the flower and the contrasty orange colour is great.', '2006-06-01 18:13:05.000000', NULL, 1),
(2476674, 340045, 23430, '<td valign="top">Very neat, symmetrical shot with no distractions. Well composed.</td>', 'Very neat, symmetrical shot with no distractions. Well composed.', '2006-06-01 18:14:51.000000', NULL, 1),
(2476677, 340182, 44579, '<td valign="top">Love this photo. The blurred train makes me feel like I am watching a movie. I keep looking at the picture expecting it to start moving. Wonderful capture. 10.</td>', 'Love this photo. The blurred train makes me feel like I am watching a movie. I keep looking at the picture expecting it to start moving. Wonderful capture. 10.', '2006-06-01 18:15:19.000000', NULL, 1),
(2476681, 339780, 23430, '<td valign="top">Nice and clear with good lighting. I think the slicing through the hands doesn''t quite look right though.</td>', 'Nice and clear with good lighting. I think the slicing through the hands doesn''t quite look right though.', '2006-06-01 18:17:04.000000', NULL, 1),
(2476687, 340697, 44579, '<td valign="top">Very cool idea, doesn''t really work well as a picture though because there is nothing to really grab your attention.</td>', 'Very cool idea, doesn''t really work well as a picture though because there is nothing to really grab your attention.', '2006-06-01 18:18:14.000000', NULL, 1),
(2476690, 339447, 23430, '<td valign="top">Like the S shape and overall composition. Great lyric to suit.</td>', 'Like the S shape and overall composition. Great lyric to suit.', '2006-06-01 18:18:56.000000', NULL, 1),
(2476692, 340144, 23430, '<td valign="top">This is a fun shot. The idea and the characters are great. The less than full size lets you down a little bit, but still a good shot.</td>', 'This is a fun shot. The idea and the characters are great. The less than full size lets you down a little bit, but still a good shot.', '2006-06-01 18:21:30.000000', NULL, 1),
(2476713, 339173, 55767, '<td valign="top">amazing capture</td>', 'amazing capture', '2006-06-01 18:30:03.000000', NULL, 1),
(2476723, 340454, 43774, '<td valign="top">Not sure this is what I would think of when I hear the song "Eleanor Rigby". Perhaps you are trying to convey "the lonely people" but I would picture an older woman near or in a church.</td>', 'Not sure this is what I would think of when I hear the song "Eleanor Rigby". Perhaps you are trying to convey "the lonely people" but I would picture an older woman near or in a church.', '2006-06-01 18:34:28.000000', NULL, 1),
(2476726, 340161, 16402, '<td valign="top">Sure looks overly noisy.</td>', 'Sure looks overly noisy.', '2006-06-01 18:34:51.000000', NULL, 1),
(2476732, 340530, 23430, '<td valign="top">Great stop action. The timing and expressions are perfect. The slight blur of the ball and nothing else looks good. I like the amount of space you''ve left around the people. DOF is good and exposure is good. Well done.</td>', 'Great stop action. The timing and expressions are perfect. The slight blur of the ball and nothing else looks good. I like the amount of space you''ve left around the people. DOF is good and exposure is good. Well done.', '2006-06-01 18:37:02.000000', NULL, 1),
(2476733, 338855, 43774, '<td valign="top">Beautiful colours and composition. One of the top images.</td>', 'Beautiful colours and composition. One of the top images.', '2006-06-01 18:38:19.000000', NULL, 1),
(2476738, 340556, 19959, '<td valign="top">LOL</td>', 'LOL', '2006-06-01 18:43:28.000000', NULL, 1),
(2476787, 340501, 16402, '<td valign="top">Exceptionally well done. Nice dusk exposure and great ghost image. Bet it was fun to do as well.</td>', 'Exceptionally well done. Nice dusk exposure and great ghost image. Bet it was fun to do as well.', '2006-06-01 19:07:58.000000', NULL, 1),
(2476812, 338855, 44878, '<td valign="top">Your colours ard focus are both spot on, but this is a George Harrison Song<br/>not a Beatles song, but dont let it bother you !<br/>Well Done</td>', 'Your colours ard focus are both spot on, but this is a George Harrison Songnot a Beatles song, but dont let it bother you !Well Done', '2006-06-01 19:20:23.000000', NULL, 1),
